package main

import (
	"flag"
	"fmt"
)

// Empty in source; the linker fills these via -ldflags -X.
var (
	version = "dev"
	commit  = "none"
	date    = "unknown"
)

func main() {
	showVersion := flag.Bool("version", false, "print version and exit")
	flag.Parse()
	if *showVersion {
		fmt.Printf("app %s (commit %s, built %s)\n", version, commit, date)
		return
	}
	// ... normal startup ...
}

/* Reproducible build (bash)
VERSION=$(git describe --tags --always)
COMMIT=$(git rev-parse --short HEAD)
# Commit time, NOT wall-clock $(date): deterministic per commit.
DATE=$(git show -s --format=%cI HEAD)
LDFLAGS="-s -w -buildid= \
  -X main.version=${VERSION} \
  -X main.commit=${COMMIT} \
  -X main.date=${DATE}"

CGO_ENABLED=0 go build -trimpath -ldflags "${LDFLAGS}" -o dist/app ./cmd/app
*/
